#!/usr/bin/env bash
set -euo pipefail
ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"

PATCH_FILE="$(mktemp)"
export PATCH_FILE
python3 - << 'PYEOF'
import base64, os, pathlib
b64 = """"""
path = os.environ["PATCH_FILE"]
data = base64.b64decode(b64)
pathlib.Path(path).write_bytes(data)
print(f"Wrote patch ({len(data)} bytes)")
PYEOF

echo "==> Applying Phase 1 theme patch..."
git apply --check "$PATCH_FILE"
git apply "$PATCH_FILE"
rm -f "$PATCH_FILE"

echo "==> Committing..."
git add -A
if git diff --cached --quiet; then
  echo "No changes to commit — theme may already be applied."
else
  git commit -m "Phase 1: maroon/gold theme, Playfair+Inter fonts, matrimonial logo (v1.2.2+106)"
fi

echo "==> Pushing to GitHub..."
git push origin main

echo
echo "Build will start automatically. Watch:"
echo "https://github.com/rekhavijay9890-ops/RishtaBook-v2/actions"
echo "Download when ready:"
echo "https://github.com/rekhavijay9890-ops/RishtaBook-v2/releases/latest"
